{id:'npj',group:'vr',journal:'npj Digital Medicine · 2024 · 7:219',title:'A portable and efficient dementia screening tool using eye tracking machine learning and virtual reality',authors:'Xu Y, Zhang C, Pan B, Yuan Q, Zhang X',n:'201 participants',result:'MoCA correlation r = 0.90; sensitivity 88.5%; specificity 83%',summary:'VECA combined VR eye tracking with machine learning to estimate MoCA scores and classify cognitive impairment. The study used five-fold cross-validation.',scope:'VR eye-tracking assessment research; the paper includes Shenzhen Yiwei Technology affiliations. Commercial-model equivalence needs documentation.',limit:'Shenzhen cohort; no cross-center training/testing. Screening agreement does not establish home-training benefit, disease prevention or diagnostic certainty.',doi:'10.1038/s41746-024-01206-5',file:'npj-vr-eye-tracking'},
{id:'mri',group:'vr',journal:'Chinese Journal of Magnetic Resonance Imaging · 2024 · 15(6):49–53',title:'Application value of structural MRI combined with computerized cognitive assessment based on VR eye-tracking technology in early diagnosis of Alzheimer’s disease',authors:'Wei Z et al.',n:'135 participants · 77 early AD / 58 cognitively unimpaired',result:'Combined AUC 0.825 vs hippocampal-volume-only AUC 0.629',summary:'A five-minute VR eye-tracking assessment was studied alongside structural MRI. Adding the assessment score improved discrimination compared with hippocampal volume alone (P < 0.001).',scope:'Clinical assessment plus imaging; not a home rehabilitation trial.',limit:'Single-site clinical sample. The combined result requires MRI and must not be attributed to the headset alone.',doi:'10.12015/issn.1674-8034.2024.06.007',file:'mri-vr-assessment'},
{id:'bmc',group:'related',journal:'BMC Public Health · 2024 · 24:1206',title:'Community screening for dementia among older adults in China: a machine learning-based strategy',authors:'Zhang Y et al.',n:'823 adults aged 65 years and older',result:'MLP AUC 0.83 ± 0.04 vs AD8 baseline AUC 0.65',summary:'Machine-learning models combined selected AD8 questions with health characteristics in the SHARE community cohort.',scope:'Related community-screening methodology. This study did not test a VR device or demonstrate QuickMind efficacy.',limit:'Performance relates to this cohort, selected health features and the study reference assessment; it is not a VR product performance claim.',doi:'10.1186/s12889-024-18692-7',file:'bmc-community-screening'},
{id:'cnbc',group:'related',journal:'American Journal of Alzheimer’s Disease & Other Dementias · 2024 · 39',title:'Development and Validation of an Automatic Computerized Neurocognitive Battery in Chinese',authors:'Zhang J, Hong Z, Yang L, Li X, Ye F',n:'86 volunteers · ages 51–82',result:'Manual/system scoring correlation 0.904–1.0',summary:'The CNBC provided automated testing and scoring. Correlations with paired paper-based measures ranged from 0.256 to 0.666.',scope:'Related computerized-assessment validation. It is not a VR rehabilitation study; supplied material does not establish QuickMind product equivalence.',limit:'Preliminary Chinese-speaking volunteer sample; score agreement is not treatment efficacy or diagnostic accuracy.',doi:'10.1177/15333175241271910',file:'computerized-battery'}
